#!/usr/bin/env bash
set -euo pipefail

# License-clean synthetic test of the exact inner E2E script generated by
# e2e-test.sh. No Delphi/Wine/Docker/image/installer payload is used here.
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
TMP="$(mktemp -d)"
trap 'rm -rf -- "${TMP}"' EXIT
MOCK_BIN="${TMP}/bin"
mkdir -p "${MOCK_BIN}"

# Extract the quoted heredoc that is sent to the disposable container.
awk '
    /^cat > / && /<<\047EOF\047$/ { inside=1; next }
    inside && /^EOF$/ { exit }
    inside { print }
' "${SCRIPT_DIR}/e2e-test.sh" > "${TMP}/run_test.sh"
if [[ ! -s "${TMP}/run_test.sh" ]]; then
    echo "ERROR: could not extract generated container test script" >&2
    exit 1
fi
bash -n "${TMP}/run_test.sh"

cat > "${MOCK_BIN}/wine" <<'MOCK_WINE'
#!/usr/bin/env bash
set -euo pipefail
case "${1:-}" in
    IdrTestConsole.exe)
        if [[ "${FAKE_CASE}" == console_error ]]; then
            exit 37
        fi
        if [[ "${FAKE_CASE}" == console_no_marker ]]; then
            echo "Console exited without its completion marker"
        else
            echo "[IDR_FEATURE:done] console testcase completed"
        fi
        ;;
    IdrTestGui.exe)
        case "${FAKE_CASE}" in
            gui_error) exit 38 ;;
            gui_missing) : ;;
            gui_bad) printf 'incorrect completion\n' > idr_test_artifact.txt ;;
            *) printf 'Automated interaction successful.\n' > idr_test_artifact.txt ;;
        esac
        ;;
    *) : ;; # fake installer and uninstaller
esac
MOCK_WINE
chmod +x "${MOCK_BIN}/wine"

# Avoid host display services and 2-second setup sleeps in these pure mocks.
for cmd in Xvfb wineboot wineserver sleep; do
    printf '#!/bin/sh\nexit 0\n' > "${MOCK_BIN}/${cmd}"
    chmod +x "${MOCK_BIN}/${cmd}"
done

failures=0
run_case() {
    local label="$1" expected="$2" stale="${3:-false}"
    local prefix="${TMP}/${label}-prefix"
    local installed="${prefix}/drive_c/Program Files/IdrTestcase"
    local rc=0
    mkdir -p "${installed}"
    for binary in IdrTestGui.exe IdrTestConsole.exe unins000.exe; do
        printf 'placeholder executable for mock only\n' > "${installed}/${binary}"
    done
    if [[ "${stale}" == true ]]; then
        printf 'Automated interaction successful.\n' > "${installed}/idr_test_artifact.txt"
    fi
    if (
        cd "${TMP}"
        PATH="${MOCK_BIN}:${PATH}" \
          WINEPREFIX="${prefix}" APP_NAME="IdrTestcase" \
          INSTALLER_NAME="Synthetic-Setup.exe" FAKE_CASE="${label}" \
          bash "${TMP}/run_test.sh"
    ) > "${TMP}/${label}.log" 2>&1; then
        rc=0
    else
        rc=$?
    fi
    if [[ "${rc}" -ne "${expected}" ]]; then
        echo "FAIL ${label}: expected status ${expected}, got ${rc}" >&2
        cat "${TMP}/${label}.log" >&2
        failures=$((failures + 1))
    else
        echo "PASS ${label} (status ${rc})"
    fi
}

run_case console_error 37
run_case console_no_marker 1
run_case gui_error 38
run_case gui_missing 1 true
run_case gui_bad 1
run_case success 0

# A human-owned host script must be preserved before build, packaging or Docker.
HOST_WORK="$TMP/host-script-refusal"
mkdir -p "$HOST_WORK/scripts" "$HOST_WORK/build"
cp "$SCRIPT_DIR/e2e-test.sh" "$HOST_WORK/scripts/e2e-test.sh"
printf 'human-owned-script\n' > "$HOST_WORK/build/run_test_in_container.sh"
cat > "$MOCK_BIN/docker" <<'MOCK_DOCKER'
#!/usr/bin/env bash
set -euo pipefail
printf 'docker-invoked\n' >> "$GUARD_TRACE"
exit "${SIM_DOCKER_RC:-99}"
MOCK_DOCKER
chmod +x "$MOCK_BIN/docker"
host_rc=0
PATH="$MOCK_BIN:$PATH" GUARD_TRACE="$TMP/docker-guard-trace.log" \
  bash "$HOST_WORK/scripts/e2e-test.sh" > "$TMP/host-script-refusal.log" 2>&1 || host_rc=$?
if [[ "$host_rc" -eq 2 ]] &&
   grep -Fq 'IDR_E2E_REFUSED reason=existing_or_symlinked_host_script action=none' "$TMP/host-script-refusal.log" &&
   [[ "$(cat "$HOST_WORK/build/run_test_in_container.sh")" == human-owned-script ]] &&
   [[ ! -e "$TMP/docker-guard-trace.log" ]]; then
    echo "PASS preexisting-host-script-refusal (status 2; no build or Docker)"
else
    echo "FAIL preexisting-host-script-refusal (status $host_rc)" >&2
    failures=$((failures + 1))
fi

# Verify successful repeat use and a failing Docker exit clean only the
# newly generated, unmodified host driver (never the preexisting sentinel).
LIFECYCLE_WORK="${TMP}/host-script-lifecycle"
mkdir -p "${LIFECYCLE_WORK}/scripts"
cp "${SCRIPT_DIR}/e2e-test.sh" "${LIFECYCLE_WORK}/scripts/e2e-test.sh"
cat > "${LIFECYCLE_WORK}/scripts/build-binaries.sh" <<'FAKE_BUILD'
#!/usr/bin/env bash
set -euo pipefail
printf 'mock-build-only\\n'
FAKE_BUILD
cat > "${LIFECYCLE_WORK}/scripts/package-installer.sh" <<'FAKE_PACKAGE'
#!/usr/bin/env bash
set -euo pipefail
root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
mkdir -p "${root}/build/installer/dist"
printf 'mock-installer-not-an-executable\\n' > "${root}/build/installer/dist/IdrTestcase-Setup.exe"
FAKE_PACKAGE
chmod +x "${LIFECYCLE_WORK}/scripts/build-binaries.sh" "${LIFECYCLE_WORK}/scripts/package-installer.sh"
run_host_lifecycle() {
    local label="$1" expected="$2" rc=0
    PATH="${MOCK_BIN}:${PATH}" GUARD_TRACE="${LIFECYCLE_WORK}/docker.calls" SIM_DOCKER_RC="${expected}" \\
      bash "${LIFECYCLE_WORK}/scripts/e2e-test.sh" > "${LIFECYCLE_WORK}/${label}.log" 2>&1 || rc=$?
    if [[ "${rc}" -eq "${expected}" &&
          ! -e "${LIFECYCLE_WORK}/build/run_test_in_container.sh" &&
          ! -L "${LIFECYCLE_WORK}/build/run_test_in_container.sh" ]] &&
          grep -Fq '=== Step 3: Running E2E Test in Container ===' "${LIFECYCLE_WORK}/${label}.log"; then
        printf 'PASS host-script-lifecycle-%s (status %s; owned driver cleaned)\\n' "${label}" "${rc}"
    else
        printf 'FAIL host-script-lifecycle-%s (status %s)\\n' "${label}" "${rc}" >&2
        failures=$((failures + 1))
    fi
}
run_host_lifecycle first-success 0
run_host_lifecycle repeat-success 0
run_host_lifecycle docker-failure 49

if [[ "${failures}" -ne 0 ]]; then
    echo "FAIL: ${failures} synthetic E2E contract checks" >&2
    exit 1
fi
echo "PASS: 10/10 synthetic E2E contract checks (NOT product qualification)"
